excels.excel:

EXPORT WITH SHEET="员工档案名册", HEADER=true,
    MAPPING={"a":"工号","b":"姓名","c":"部门","d":"职位","e":"入职日期","f":"月薪","g":"年薪"},
    FORMAT={"e":"yyyy-MM-dd","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        G2:'F2*12',G3:'F3*12',G4:'F4*12',G5:'F5*12',G6:'F6*12',G7:'F7*12',
        F8:'SUM(F2:F7)',G8:'SUM(G2:G7)'
    },
    STYLE={ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}}
